let capstoneStep=0,capstonePoints=0,capstoneResponses=[],capstoneNeedsRecovery=false;
function resetCapstone(){capstoneStep=0;capstonePoints=0;capstoneResponses=[];capstoneNeedsRecovery=false;renderCapstone()}
function renderCapstone(){
 const v=$('view');
 if(capstoneStep>=capstoneScenes.length){complete(8);v.innerHTML=`<h2>Clinical capstone · Debrief</h2><div class="preceptor"><img class="avatar" src="professor-morgan.jpg" alt="Professor Morgan"><div><strong>Professor Morgan, RDMS · Virtual Preceptor</strong><p>You completed a full clinical verification encounter. Safe practice means pausing, escalating, verifying authorized corrections, and closing the communication loop.</p></div></div><h3>First-choice score: ${capstonePoints} / 5</h3><p>${capstonePoints>=4?'You met the practice target of at least four correct initial decisions.':'Review the decisions you missed and repeat the encounter to strengthen your first-choice accuracy.'} Recovery steps provided guided practice but did not add points.</p><div class="capstone-state">${capstoneResponses.map((x,i)=>`<p><strong>Decision ${i+1}:</strong> ${x?'Correct on first choice':'Needed guided recovery'}</p>`).join('')}</div><button class="primary" onclick="renderReadiness('after');attachSonoVoiceControls()">Take the follow-up knowledge check →</button> <button onclick="resetCapstone();attachSonoVoiceControls()">Replay the encounter</button> <button onclick="printReport('Integrated clinical capstone',capstonePoints,5)">Print scorecard</button>`;return;}
 const c=capstoneScenes[capstoneStep];
 v.innerHTML=`<h2>Integrated clinical capstone</h2><p class="stepnote">Decision ${capstoneStep+1} of ${capstoneScenes.length} · A complete simulated patient encounter</p><div class="capstone-path">${['Verify','Escalate','Clarify','Recheck','Handoff'].map((x,i)=>`<span class="${i===capstoneStep?'now':''}">${i+1}. ${x}</span>`).join('')}</div><h3>${c.title}</h3><div class="preceptor"><img class="avatar" src="professor-morgan.jpg" alt="Professor Morgan"><div><strong>Professor Morgan, RDMS · Virtual Preceptor</strong><p>${c.speech}</p></div></div>${capstoneStep===0?documents(cases[1]):''}<div class="capstone-state"><strong>Current encounter:</strong> ${capstoneStep===0?'Order received · Verification pending':capstoneScenes[capstoneStep-1].effect}</div><p><strong>Choose the safest action.</strong> Your first choice counts toward the score. If you make an unsafe choice, the encounter will pause for a guided recovery step.</p><div class="options">${c.options.map((o,i)=>`<button class="option" onclick="answerCapstone(${i})">${o}</button>`).join('')}</div><div id="capstoneFeedback" role="status" aria-live="polite"></div>`;
}
function answerCapstone(i){
 if(capstoneNeedsRecovery||document.querySelector('#capstoneFeedback button'))return;
 const c=capstoneScenes[capstoneStep],ok=i===c.correct;
 capstoneResponses.push(ok);if(ok)capstonePoints++;
 document.querySelectorAll('#view .option').forEach(b=>b.disabled=true);
 capstoneNeedsRecovery=!ok;
 $('capstoneFeedback').innerHTML=`<div class="feedback ${ok?'good':'warn'}"><strong>${ok?'Safe clinical decision.':'Unsafe pathway · The encounter is paused.'}</strong><p>${ok?c.good:c.bad}</p><p class="capstone-state ${ok?'':'capstone-alert'}"><strong>${ok?'Consequence:':'What happens next:'}</strong> ${ok?c.effect:'The discrepancy remains unresolved. No scan may begin.'}</p>${ok?'':`<p><strong>Guided recovery:</strong> ${c.recovery}</p>`}</div><button class="primary" onclick="${ok?'nextCapstone()':'recoverCapstone()'}">${ok?'Continue encounter →':'Complete guided recovery →'}</button>`;
 collectSonoSegments();narrateNewFeedback('#capstoneFeedback .feedback');
}
function recoverCapstone(){capstoneNeedsRecovery=false;const c=capstoneScenes[capstoneStep];$('capstoneFeedback').innerHTML=`<div class="feedback good"><strong>Recovery completed.</strong><p>${c.recovery}</p><p>${c.effect}</p></div><button class="primary" onclick="nextCapstone()">Continue after verification →</button>`;narrateNewFeedback('#capstoneFeedback .feedback');}
function nextCapstone(){capstoneStep++;renderCapstone();attachSonoVoiceControls();scrollToLesson();}
const baseRenderWithVoice=render;
render=function(){baseRenderWithVoice();if(current===8||current===9)attachSonoVoiceControls();};

render();